package com.autojobapply;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.WaitUntilState;
public final class PlaywrightSmokeTest { public static void main(String[] args) { long start=System.nanoTime(); System.out.println("BEFORE_PLAYWRIGHT_CREATE"); try(Playwright p=Playwright.create()){System.out.println("AFTER_PLAYWRIGHT_CREATE");System.out.println("BEFORE_CHROME_LAUNCH");try(Browser b=p.chromium().launch(new BrowserType.LaunchOptions().setChannel("chrome").setHeadless(true))){System.out.println("AFTER_CHROME_LAUNCH");Page page=b.newPage();page.navigate("data:text/html,<title>Local</title>",new Page.NavigateOptions().setWaitUntil(WaitUntilState.DOMCONTENTLOADED).setTimeout(5000));System.out.println("LOCAL_NAVIGATION_PASSED");}}catch(Exception e){System.out.println("PLAYWRIGHT_FAILED: "+e.getMessage());}finally{System.out.println("ELAPSED_MS="+((System.nanoTime()-start)/1_000_000));}} }
